(function(){
'use strict';
const E=window.AudienceEngine,KEY='utup.audience.demo.v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['任务创建','需求理解','策略确认','条件构建','执行评估','资产沉淀'];
const outputs=['任务信息','需求理解','策略依据','筛选条件','人群结果','保存与复盘'];
let operationEpoch=0,drawerReturn=null;
const sessionUi=new Map();
let historyOpen=true,historySearch='',executionTab='audience',draftQuery='',draftPlatform='',artifactView=null,workflowBusy=false;
const labels={object:'目标人群 / 业务对象',action:'目标行为与使用意图',window:'时间窗口（天）',domain:'业务域',definition:'关键概念口径',platform:'生效平台 / 使用入口',exclude:'排除条件',success:'成功标准',experiment:'实验 ID 与目标指标'};
const hints={object:'例如：同时具备出游意向和住宿偏好的用户',action:'例如：召回、复购、品牌触达',window:'“近期”需要明确为具体天数',domain:'生服 或 跨域；LDMP 仅生服',definition:'明确兴趣信号、消费分层或价格带的判断口径',platform:'例如：生服运营入口',exclude:'明确排除对象，或填写无额外排除',success:'例如：得到可供业务抽检的人群包；不预填收益',experiment:'演示实验标识和指标，例如 DEMO-EXP-01 / 核销'};
let host,options={},tasks=[],active=null,view='home',scope='portal',picked=new Set(['balanced']),upload=[],seedAsset=null,message='',runFailure='',running=false,compareVersion=null;
try{tasks=JSON.parse(localStorage.getItem(KEY)||'[]').filter(t=>t.schema===1);}catch(e){tasks=[];}
const current=()=>tasks.find(t=>t.id===active);
const button=(text,act,cls='',disabled=false,extra='')=>`<button type="button" class="${cls}" data-action="${act}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(tasks));}catch(e){message='浏览器存储不可用，任务仅保留在本次页面中';}}
function notify(s){message=s;render();setTimeout(()=>{if(message===s){message='';const n=host?.querySelector('.toast');if(n)n.remove();}},3500);}
function needTask(){const t=current();if(!t)throw Error('请先创建任务');return t;}
function state(t){if(t.activity?.at(-1)?.status==='running')return '处理中';if(t.activity?.at(-1)?.status==='cancelled')return '已暂停';if(t.invalid)return '已失效';if(t.blocker)return '受阻';if(t.archived)return '已归档';if(t.result?.approved)return '待归档';if(t.attempts>=3)return '转人工处理';if(t.stage===3)return E.validation(t).length?'需处理缺口':'条件就绪';if(t.stage===4&&!t.result)return running?'执行中':'待执行';return ['已创建','待补充','方案待确认','待执行','结果待复核','策略档案'][t.stage];}
function mount(node,opts={}){host=node;options=opts;try{tasks=JSON.parse(localStorage.getItem(KEY)||'[]').filter(t=>t.schema===1);}catch(e){}view=opts.view||'home';if(view==='home'&&opts.resume&&current())view='task';for(const task of tasks){E.cancelActivity(task,'页面重新打开，上次未完成的处理已中断');for(const h of task.handoffs||[])if(['prepared','running'].includes(h.status))h.status='cancelled';}persist();host.classList.add('aud');historyOpen=host.clientWidth>=850;render();}
function rememberSession(){if(!host)return;const id=host.dataset.task;if(!id)return;const stream=host.querySelector('.aud-chat-stream');if(stream)sessionUi.set(id,{scroll:stream.scrollTop,bottom:stream.scrollHeight-stream.scrollTop-stream.clientHeight<90});}
function render(){
 if(!host||!host.isConnected)return;
 rememberSession();
 const historyScroll=host.querySelector('.aud-session-list')?.scrollTop||0,t=current(),sameTask=host.dataset.task===active;
 const opened=[...host.querySelectorAll('details[data-receipt][open]:not([data-live])')].map(n=>n.dataset.receipt);
 const drawerScroll=host.querySelector('.aud-drawer-body')?.scrollTop||0,oldDrawer=host.dataset.drawer;
 const focused=host.contains(document.activeElement)?document.activeElement:null,focusId=focused?.id,focusAction=focused?.dataset.action,focusTab=focused?.dataset.tab;
 host.dataset.task=active||'';host.dataset.drawer=artifactView===null?'':String(artifactView);
 host.classList.toggle('is-home',view==='home');host.classList.toggle('is-task',view==='task');
 host.innerHTML=`<div class="aud-session-shell ${historyOpen?'history-open':'history-closed'}" >${sessionSidebar()}${button('关闭历史会话','toggle-history','aud-history-backdrop',false,'aria-label="关闭历史会话侧栏"')}<div class="aud-session-main"><header class="head between"><div class="studio-brand"><span class="brand-icon">✦</span><div><h1>${view==='archive'?'已保存模板':'圈人 Agent'}</h1><p>${view==='task'&&t?esc(t.title):'把业务目标，变成可执行的人群方案'}</p></div></div><div class="row">${view==='task'&&t?badge(state(t),t.blocker?'amber':'green'):''}<details class="aud-demo-note"><summary>演示版</summary><p>当前使用模拟资产与执行结果，尚未接入真实模型、数据服务和投放平台。任务仅保存在当前浏览器。</p></details>${view==='task'?button('执行过程与产物','open-deliverables','quiet'):button('已保存模板','archives','quiet')}</div></header><div class="aud-working-area ${t&&artifactView!==null&&view==='task'?'has-detail':''}">${view==='home'?home():view==='archive'?archives():t?workspace(t):home()}${t&&artifactView!==null&&view==='task'?artifactDrawer(t):''}</div></div></div>${message?`<div role="status" class="toast">${esc(message)}</div>`:''}`;
 bind();const list=host.querySelector('.aud-session-list');if(list)list.scrollTop=historyScroll;
 if(sameTask)host.querySelectorAll('details[data-receipt]').forEach(n=>{if(opened.includes(n.dataset.receipt))n.open=true;});
 const stream=host.querySelector('.aud-chat-stream'),pos=sessionUi.get(active);if(stream){stream.scrollTop=pos?(pos.bottom?stream.scrollHeight:pos.scroll):stream.scrollHeight;if(!workflowBusy&&host.dataset.wasBusy==='true'){const response=host.querySelector('.aud-current-response');if(response)stream.scrollTop+=response.getBoundingClientRect().top-stream.getBoundingClientRect().top-20;}}host.dataset.wasBusy=String(workflowBusy);
 const drawer=host.querySelector('.aud-drawer');if(drawer){const body=drawer.querySelector('.aud-drawer-body');if(sameTask&&oldDrawer===String(artifactView))body.scrollTop=drawerScroll;const target=focusId?drawer.querySelector('#'+CSS.escape(focusId)):focusAction?drawer.querySelector(`[data-action="${focusAction}"]${focusTab?'[data-tab="'+focusTab+'"]':''}`):null;if(!sameTask||oldDrawer!==String(artifactView))drawer.querySelector('[data-action="close-artifact"]')?.focus({preventScroll:true});else target?.focus({preventScroll:true});}
}
function sessionStamp(t){return t.lastOpened||t.history?.at(-1)?.at||t.created;}
function sessionSidebar(){const today=new Date();today.setHours(0,0,0,0);const groups=[['今天',[]],['昨天',[]],['过去 7 天',[]],['更早',[]]];tasks.slice().sort((a,b)=>new Date(sessionStamp(b))-new Date(sessionStamp(a))).forEach(t=>{const day=new Date(sessionStamp(t));day.setHours(0,0,0,0);const age=Math.round((today-day)/86400000);groups[age<=0?0:age===1?1:age<7?2:3][1].push(t);});return `<aside class="aud-session-sidebar" aria-label="历史会话"><div class="aud-history-heading">${button('☷','toggle-history','aud-history-toggle',false,`aria-label="${historyOpen?'收起':'展开'}历史会话" aria-expanded="${historyOpen}"`)}<b>历史会话</b></div><div class="aud-history-body">${button('＋ 新建会话','home','aud-new-session',false)}<label class="aud-sr-only" for="aud-history-search">搜索历史会话</label><input id="aud-history-search" placeholder="搜索历史会话" value="${esc(historySearch)}"><nav class="aud-session-list" aria-label="历史会话列表">${groups.filter(([,items])=>items.length).map(([label,items])=>`<section class="aud-session-group"><h3>${label}</h3>${items.map(t=>`<button type="button" class="aud-session-entry ${active===t.id&&view==='task'?'active':''}" data-action="resume" data-id="${esc(t.id)}" data-history-search="${esc((t.query+' '+t.title).toLowerCase())}" ${active===t.id&&view==='task'?'aria-current="page"':''} title="${esc(t.query)}"><span>${esc(t.title)}</span><em>${esc(t.query)}</em><small><i class="${t.blocker?'blocked':t.archived?'saved':''}"></i>${esc(state(t))}${t.archived?' · 已存模板':''}</small></button>`).join('')}</section>`).join('')}</nav><p class="aud-history-empty" ${tasks.length?'hidden':''}>还没有历史会话<br>新建任务后会自动保留在这里。</p><p class="aud-history-no-match" hidden>没有匹配的会话</p><div class="aud-history-bottom">${button('▧ 已保存模板','archives',view==='archive'?'active':'',false)}<p>会话自动保存在当前浏览器</p></div></div></aside>`;}
function filterSessionHistory(){const term=historySearch.trim().toLowerCase();let visible=0;host.querySelectorAll('.aud-session-entry').forEach(n=>{n.hidden=!n.dataset.historySearch.includes(term);if(!n.hidden)visible++;});host.querySelectorAll('.aud-session-group').forEach(n=>{n.hidden=![...n.querySelectorAll('.aud-session-entry')].some(b=>!b.hidden);});const empty=host.querySelector('.aud-history-no-match');if(empty)empty.hidden=!tasks.length||visible>0;}
function section(title,subtitle,body,extra=''){return `<section class="work-card"><div class="work-card-title between"><div><h3>${title}</h3>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${extra}</div><div class="work-card-body">${body}</div></section>`;}
function roles(){return `<div class="aud-agent-role"><span class="agent-avatar">圈</span><div><b>圈人 Agent</b><p>理解目标、提出策略、匹配资产、把关与解释结果</p></div></div><div class="agent-connector">执行条件与版本 ↓　↑ SQL、结果或缺口</div><div class="aud-agent-role"><span class="agent-avatar secondary">理</span><div><b>用户理解 Agent</b><p>接收结构化条件，生成查询并返回执行回执</p></div></div>`;}
function artifactAvailability(t){return [true,true,t.confirmed,t.conditions.length>0,!!t.result,!!t.result?.approved];}
function activityCard(t,a){const stateNames={running:'正在处理',done:'已完成',waiting:'等待业务补充',blocked:'已阻断',cancelled:'已中断'};return `<section class="agent-activity ${a.status}" aria-label="${esc(a.title)}"><div class="between"><h3><span class="${a.status==='running'?'activity-spinner':'activity-dot'}"></span>${esc(a.status==='running'?a.title:a.title.replace('正在',' · '))}</h3>${badge(stateNames[a.status]||'待开始',a.status==='blocked'||a.status==='waiting'?'amber':a.status==='done'?'green':'')}</div><p class="activity-meta">本地流程演示 · V${a.version} · ${esc(a.started.slice(11,19))}</p><ol class="agent-todos">${a.items.map((item,i)=>`<li class="todo-${item.status}"><span class="todo-symbol">${item.status==='done'?'✓':item.status==='blocked'?'!':item.status==='waiting'?'?':item.status==='cancelled'?'–':i+1}</span><div><div class="between"><b>${esc(item.title)}</b><span class="todo-owner">${esc(item.owner)}</span></div>${item.status==='done'?'<details class="aud-todo-receipt"><summary>依据与产物</summary>':''}${item.summary?`<p>${esc(item.summary)}</p>`:''}${item.status==='done'&&item.artifact!==null&&a.version===t.version&&artifactAvailability(t)[item.artifact]?button('查看'+outputs[item.artifact],'view-artifact','quiet small',workflowBusy,`data-stage="${item.artifact}"`):''}${item.status==='done'?'</details>':''}</div></li>`).join('')}</ol>${a.reason?`<p class="muted">${esc(a.reason)}</p>`:''}</section>`;}
function handoffCard(t){const h=t.handoffs?.at(-1);if(!h||h.version!==t.version)return '';return `<section class="handoff-card"><div class="between"><b>圈人 Agent <span>→</span> 用户理解 Agent</b>${badge(h.status==='completed'?'回执已校验':h.status==='failed'?'失败已返回':h.status==='cancelled'?'已取消':'模拟委托中',h.status==='failed'?'amber':'')}</div><p>发送：人群定义、条件与资产版本、时间窗、排除规则、种子引用。</p><p>返回：${h.response?.status==='failed'?esc(h.response.reason):h.response?'SQL、模拟人群结果、执行状态与质量提示。':'等待结构化回执；用户理解 Agent 不自行修改业务目标。'}</p><details><summary>查看委托与回执</summary><div class="receipt-meta">任务 ${esc(h.taskId)} · V${h.version}<br>请求 ${esc(h.requestId)}<br>幂等标识 ${esc(h.idempotencyKey)}</div><p class="muted">版本不一致的回执拒绝采用；权限或字段缺口返回圈人 Agent 处理。</p><pre>${esc(JSON.stringify(h,null,2))}</pre></details></section>`;}
function conditionOverview(t){if(!t.conditions.length)return '';return `<section class="aud-condition-overview"><div class="between"><h3>本次圈选条件</h3>${badge(t.conditions.length+' 条 · V'+t.version)}</div><p class="muted">必须满足 AND · 任一满足 OR · 排除 NOT</p>${['必须满足','任一满足','排除','辅助分层','频控','黑白名单'].map(group=>{const rows=t.conditions.filter(c=>c.group===group);return rows.length?`<div class="aud-rule-group ${group==='排除'?'exclusion':''}"><h4>${esc(group)}<span>${rows.length} 条</span></h4>${rows.map(c=>`<div class="aud-rule"><b>${esc(c.name)}</b><p>${esc(c.value)}</p><small>${esc(c.domain)} · ${esc(c.assetVersion)}${c.locked?' · 规则锁定':''}</small></div>`).join('')}</div>`:'';}).join('')}</section>`;}
function chatHistory(t){if(!t.chat){t.chat=[{kind:'user',text:t.versions?.[0]?.query||t.query,version:t.versions?.[0]?.version||t.version}];for(const a of t.activity||[])t.chat.push({kind:'activity',id:a.id});}return t.chat;}
function addChat(t,text){chatHistory(t).push({kind:'user',text,version:t.version,at:new Date().toISOString()});}
function receipt(t,a){const live=a.status==='running',done=a.items.filter(x=>x.status==='done').length,last=a.items.find(x=>['running','waiting','blocked'].includes(x.status));return `<div class="aud-chat-agent"><span class="aud-chat-avatar">✦</span><div class="aud-chat-message"><details class="aud-operation" data-receipt="${esc(a.id)}" ${live?'data-live':''} ${live?'open':''}><summary><span class="${live?'activity-spinner':'aud-receipt-mark'}">${live?'':a.status==='blocked'?'!':a.status==='waiting'?'?':a.status==='cancelled'?'–':'✓'}</span><b>${esc(a.title.replace('正在',' · '))}</b><small>${live?'进行中':a.status==='waiting'?'当时待补充':a.status==='blocked'?'需处理':a.status==='cancelled'?'已暂停':done+' 项已完成'} · V${a.version}</small></summary>${activityCard(t,a)}</details>${last?.summary&&!live?`<p class="aud-receipt-summary">${esc(last.summary)}</p>`:a.items.at(-1)?.summary?`<p class="aud-receipt-summary">${esc(a.items.at(-1).summary)}</p>`:''}${a.snapshot?`<details class="aud-chat-snapshot"><summary>已保留的${a.snapshot.result?'执行结果':'需求与条件'} · V${a.version}</summary><p>${esc(a.snapshot.query)}</p><p>${esc(a.snapshot.domain)} · 近 ${esc(a.snapshot.window)} 天</p>${a.snapshot.decisions.map(v=>`<p>${esc(v)}</p>`).join('')}${a.snapshot.conditions.map(c=>`<p>${esc(c.group)} · ${esc(c.name)} · ${esc(c.value)}</p>`).join('')}${a.snapshot.result?`<p>模拟规模 ${a.snapshot.result.size.toLocaleString()} 人；未验证业务收益。</p>`:''}</details>`:''}</div></div>`;}
function querySummary(t){return `<div class="aud-query-summary"><h3>我理解，你想找到这样一群人</h3><p>${esc(t.fields.object.value||t.query)}</p><dl><div><dt>用途</dt><dd>${esc(t.fields.action.value)}</dd></div><div><dt>范围</dt><dd>${esc(t.fields.domain.value)}${t.fields.window.value?' · 近 '+esc(t.fields.window.value)+' 天':''}</dd></div>${Object.entries(t.decisions||{}).map(([k,v])=>`<div><dt>${({interest:'兴趣依据',spending:'消费口径',dormant:'未购时间',window:'时间窗口'})[k]||'补充口径'}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${button('查看理解依据 ↗','view-artifact','quiet small',false,'data-stage="1"')}</div>`;}
function compactConditions(t){return `<div class="aud-chat-conditions"><div class="between"><h3>筛选条件汇总</h3>${button('查看与调整 ↗','view-artifact','quiet small',workflowBusy,'data-stage="3"')}</div>${['必须满足','任一满足','排除','辅助分层','频控','黑白名单'].map(group=>{const rows=t.conditions.filter(c=>c.group===group);return rows.length?`<div class="aud-chat-condition-row"><span>${group}</span><p>${rows.map(c=>`<b>${esc(c.name)}</b> ${esc(c.value)}`).join('；')}</p></div>`:'';}).join('')}<p class="aud-chat-footnote">所有条件关联当前 V${t.version}，执行前核对口径、版本与权限。</p></div>`;}
function resultMessage(t){const r=t.result;return `<div class="aud-chat-result"><div class="between"><span>人群结果 · V${r.version}</span>${badge('模拟完成','green')}</div><h3>${r.size.toLocaleString()} <small>人 · 演示规模</small></h3><p>已按确认条件生成示例人群包，筛选逻辑、SQL 与评估报告保留在同一版本中。</p><div class="aud-chat-result-footer"><span>${r.approved?'已记录业务复核':'下一步，复核这批人是否符合业务目标'}</span>${button(r.approved?'查看结果与报告 ↗':'查看结果并复核 ↗','view-artifact','primary',workflowBusy,'data-stage="4"')}</div></div>`;}
function agentWorkspace(t){const history=chatHistory(t),latest=t.activity?.at(-1);let next='';
 if(workflowBusy)next=`<div class="aud-chat-running"><span class="activity-spinner"></span>正在推进任务，操作进度记录在上方${button('暂停','pause-workflow','quiet small')}</div>`;
 else if(latest?.status==='cancelled')next=`<div class="warnbox">任务已暂停，已完成的操作与内容都已保留。${button('继续处理','resume-workflow','primary')}</div>`;
 else if(t.stage<=2)next=querySummary(t)+`<div class="aud-inline-action">${t.stage===2?strategies(t):center(t)}</div>`;
 else if(t.stage===3)next=compactConditions(t)+`<div class="warnbox"><b>${t.blocker?'执行前发现缺口':'条件等待核对'}</b><p>${t.blocker?esc(E.blockers[t.blocker]):'检查条件取值和资产状态，再发起执行。'}</p>${button('打开条件详情','view-artifact','primary',false,'data-stage="3"')}</div>`;
 else if(t.result)next=resultMessage(t)+(t.stage===5?`<div class="aud-chat-save"><b>${t.archived?'已保存为圈人模板':'复核已完成，可以保存为可复用方案'}</b><p>需求、策略、条件与结果一起保存。实际使用与收益由业务方后续回传。</p>${button(t.archived?'查看已保存模板':'保存为模板','view-artifact','',false,'data-stage="5"')}</div>`:'');
 else next=`<div class="warnbox"><h3>执行尚未完成</h3><p>${esc(t.runs.at(-1)?.reason||'检查执行记录后继续。')}</p>${button('查看执行详情 / 重试','view-artifact','primary',false,'data-stage="4"')}</div>`;
 return `<main class="aud-chat-layout"><div class="aud-chat-stream" aria-label="任务对话"><div class="aud-chat-width"><div class="aud-chat-date">${esc(new Date(t.created).toLocaleDateString('zh-CN'))} · 会话自动保存</div>${history.map(item=>item.kind==='user'?`<div class="aud-chat-user"><div><p>${esc(item.text)}</p><small>你 · V${item.version}</small></div></div>`:(()=>{const a=t.activity?.find(x=>x.id===item.id);return a?receipt(t,a):'';})()).join('')}<div class="aud-chat-agent aud-current-response"><span class="aud-chat-avatar">✦</span><div class="aud-chat-message">${progress(t)}${next}${t.handoffs?.at(-1)?.version===t.version?button('用户理解 Agent · 查看协作记录 ↗','open-handoff','quiet small',workflowBusy):''}</div></div></div></div><div class="aud-chat-compose-wrap"><div class="aud-chat-compose"><label class="aud-sr-only" for="aud-followup">调整后的完整圈人需求</label><textarea id="aud-followup" placeholder="需要调整？输入完整的新需求，或点下方「修改当前需求」……" ${workflowBusy?'disabled':''}>${esc(t.chatDraft||'')}</textarea><div class="between">${button('修改当前需求','edit-current-query','quiet small',workflowBusy)}<span class="aud-compose-hint">新需求生成新版本，保留原记录</span>${button('发送 ↑','send-followup','primary',workflowBusy||!t.chatDraft?.trim())}</div></div><p class="aud-chat-footnote">本地演示 · 展示操作、依据与结论摘要 · 结果不代表真实业务收益</p></div></main>`;
}
function artifactDrawer(t){let title='执行过程与产物',body='';const available=artifactAvailability(t);
 if(artifactView==='all')body=progress(t)+`<p class="muted">六类产物随任务推进自动保留，无需逐页操作。</p><nav class="aud-drawer-artifacts">${outputs.map((name,i)=>button(`<span><small>0${i+1}</small>${name}</span><b>${available[i]?'查看 →':'待生成'}</b>`,'view-artifact','',!available[i],`data-stage="${i}"`)).join('')}</nav>`;
 else if(artifactView==='handoff'){title='Agent 协作记录';body=roles()+handoffCard(t);}
 else{title=outputs[artifactView];if(artifactView===0)body=`<dl class="context-list"><dt>任务标识</dt><dd>${esc(t.id)}</dd><dt>业务原话</dt><dd>${esc(t.query)}</dd><dt>业务场景</dt><dd>${esc(t.title)}</dd></dl>`+left(t);
 if(artifactView===1)body=understandingTable(t);
 if(artifactView===2)body=strategyEvidence(t);
 if(artifactView===3)body=t.stage===3?conditions(t):conditionOverview(t)+button('修改条件并重新校验','revise-condition','primary',workflowBusy);
 if(artifactView===4)body=execution(t);
 if(artifactView===5)body=archiveDetail(t)+effectReview(t);}
 return `<aside class="aud-drawer aud-canvas" role="complementary" aria-labelledby="aud-drawer-title"><header><div><span>当前任务 · V${t.version}</span><h2 id="aud-drawer-title">${title}</h2></div>${button('✕','close-artifact','quiet',false,'aria-label="关闭详情"')}</header><nav class="aud-panel-tabs" aria-label="任务产物导航">${outputs.map((label,i)=>button(label,'view-artifact',artifactView===i?'active':'',!available[i],`data-stage="${i}" aria-pressed="${artifactView===i}"`)).join('')}</nav><div class="aud-drawer-body">${body}</div><footer>可继续在左侧对话 · 当前为模拟执行</footer></aside>`;
}
function stopOperation(t,reason){if(!workflowBusy||!t)return;E.cancelActivity(t,reason);for(const h of t.handoffs||[])if(['prepared','running'].includes(h.status))h.status='cancelled';operationEpoch++;workflowBusy=false;running=false;persist();}

const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function operate(t,title,items){
 if(workflowBusy)throw Error('当前任务仍在处理');workflowBusy=true;artifactView=null;const epoch=++operationEpoch;
 chatHistory(t);const a=E.beginActivity(t,title,items);t.chat.push({kind:'activity',id:a.id});persist();render();
 try{for(let i=0;i<items.length;i++){
  if(epoch!==operationEpoch||current()?.id!==t.id||a.version!==t.version||a.status==='cancelled')return false;
  E.updateActivity(t,a.id,i,'running');persist();render();await pause(420);
  if(epoch!==operationEpoch||current()?.id!==t.id||a.version!==t.version||a.status==='cancelled')return false;
  try{const result=await items[i].work();const status=result?.status||'done';E.updateActivity(t,a.id,i,status,result?.summary||String(result||''));persist();render();if(status!=='done')return false;}
  catch(err){for(const h of t.handoffs||[])if(h.version===t.version&&['prepared','running'].includes(h.status)){h.status='failed';h.response={status:'failed',reason:err.message,taskId:t.id,version:t.version,requestId:h.requestId};}E.updateActivity(t,a.id,i,'blocked',err.message);E.log(t,'操作受阻：'+err.message);persist();return false;}
 }return true;}finally{if(epoch===operationEpoch){if(a.status==='done')a.snapshot={query:t.query,domain:t.fields.domain.value,window:t.fields.window.value,decisions:Object.values(t.decisions||{}),conditions:E.clone(t.conditions),result:t.result?{size:t.result.size}:null};workflowBusy=false;persist();render();}}
}
async function understandFlow(t){return operate(t,'圈人 Agent 正在整理方案',[
 {title:'识别任务类型',artifact:0,work:()=>{t.stage=1;return '识别为'+t.type+'；保留业务原话与任务标识';}},
 {title:'提取业务上下文',artifact:1,work:()=> '已整理业务对象、时间窗、数据范围与排除约束；'+E.questions(t).length+' 项关键口径待补充'},
 {title:'检索历史策略',work:()=>{const refs=tasks.filter(x=>x.id!==t.id&&x.archived&&!x.invalid&&x.scenario===t.scenario);t.historyMatches=refs.map(x=>({id:x.id,version:x.version,title:x.title}));return refs.length?'找到 '+refs.length+' 份同场景本地策略，仅作为本次参考':'没有可直接复用的本地档案；按本次需求生成，不假定历史效果';}},
 {title:'核对关键口径',work:()=>{const pending=E.questions(t);if(!['直接圈人','复用历史策略','分析转圈人'].includes(t.type))return {status:'blocked',summary:'此请求需先转译为明确的人群定义'};return pending.length?{status:'waiting',summary:'只有 '+pending.length+' 项会改变入选范围，需要业务补充；其他已明确信息直接采用'}:'关键口径完整，无需重复确认';}},
 {title:'生成候选人群策略',artifact:2,work:()=>{E.confirm(t);const ids=t.templateStrategy||['balanced'];picked=new Set([ids.includes('conservative')&&!ids.includes('balanced')?'conservative':'balanced',...(ids.includes('explore')?['explore']:[])]);return '按业务硬条件生成标准口径与窄口径；只需选择本次范围，探索分层为可选增强';}}
 ]);}
async function executeFlow(t,map=false){let req=null;const entries=[];
 if(map)entries.push({title:'映射可执行资产',artifact:3,work:()=>{E.select(t,[...picked]);return '已将策略映射为 '+t.conditions.length+' 条条件，保留 AND / OR / 排除关系与资产版本';}});
 entries.push({title:'检查条件、权限与数据范围',owner:'圈人 Agent · 规则校验',artifact:3,work:()=>{const errors=E.validation(t);if(errors.length){t.stage=3;throw Error(errors.join('、'));}t.conditionConfirmed=true;t.stage=4;return '模拟检查通过，核心条件未放宽；可以委托执行';}},
 {title:'组织执行委托',work:()=>{req=E.prepareHandoff(t);req.status='running';return '发送任务 ID、V'+t.version+'、条件单和风险约束；使用请求标识关联后续回执';}},
 {title:'生成查询方案与 SQL',owner:'用户理解 Agent（模拟）',work:()=>{req.generatedSql=E.sql(t);return '根据收到的条件生成示例 SQL；不调整用户目标或排除条件';}},
 {title:'核验 SQL 与委托版本',owner:'圈人 Agent · 规则校验',work:()=>{if(req.version!==t.version||!E.executable(t))throw Error('委托版本或执行条件发生变化，停止执行');return '委托与当前任务版本一致；查询绑定确认条件，真实 SQL 校验服务尚待接入';}},
 {title:'运行查询并回读结果',owner:'用户理解 Agent / 执行服务（模拟）',work:()=>{const run=E.run(t,runFailure||null);if(run.status==='失败'){E.acceptHandoff(t,{requestId:req.requestId,taskId:t.id,version:t.version,status:'failed',reason:run.reason});throw Error(run.reason+'；已返回圈人 Agent，未修改业务条件');}return '模拟运行完成，返回运行编号与人群结果；尚未执行真实数据查询';}},
 {title:'核对回执并解释人群',artifact:4,work:()=>{E.acceptHandoff(t,{requestId:req.requestId,taskId:t.id,version:t.version,resultVersion:t.result.version,status:'completed',sql:t.result.sql,runId:t.result.runId,audienceSize:t.result.size,quality:'模拟结果；覆盖需核实、收益待验证'});return '已校验任务与版本，输出人群解释、SQL、运行日志及评估报告，等待业务复核';}});
 const ok=await operate(t,map?'圈人 Agent 正在构建并执行方案':'圈人 Agent 正在协调执行',entries);if(ok){artifactView=4;historyOpen=false;executionTab='audience';render();}return ok;
}
async function archiveFlow(t){return operate(t,'圈人 Agent 正在沉淀本次方案',[
 {title:'核对结果与业务复核',work:()=>{if(!t.result?.approved||t.result.version!==t.version)throw Error('当前版本尚未通过业务复核');return '当前结果已复核；采纳反馈与收益验证分别记录';}},
 {title:'绑定产物与版本',work:()=> '需求、策略、条件、执行回执、评估与过程记录绑定 V'+t.version},
 {title:'保存可复用策略档案',artifact:5,work:()=>{t.archived=true;t.invalid=false;E.log(t,'保存策略档案及 Agent 操作摘要');return '已保存到当前浏览器；实际业务使用与效果证据仍待回收';}}
 ]);}

const sceneCopy={brand:['新品推广','找到对新品有兴趣的消费者','bag'],acquisition:['品牌拉新','从品类买家中发现品牌新客','plus'],recall:['老客召回','找回一段时间没有购买的用户','return'],repurchase:['复购提醒','找到进入补货周期的老客','cycle'],local:['门店获客','发现周边有相关兴趣的用户','pin'],cross:['跨域找人','发掘其他业务域的消费潜力','cross']};
function icon(name){const paths={spark:'M12 3l2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z',bag:'M5 7h14l1 13H4L5 7ZM8 8V6a4 4 0 0 1 8 0v2',plus:'M12 5v14M5 12h14',return:'M7 7h7a6 6 0 0 1 0 12H8M7 3 3 7l4 4',cycle:'M19 8a8 8 0 0 0-13-2L3 9m0-5v5h5M5 16a8 8 0 0 0 13 2l3-3m0 5v-5h-5',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM14 10a2 2 0 1 1-4 0 2 2 0 1 1 4 0',cross:'M3 7h14m-4-4 4 4-4 4M21 17H7m4-4-4 4 4 4',attach:'m9 13 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l8-8',arrow:'M5 12h14m-6-6 6 6-6 6',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.spark).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`;}
function home(){return `<main class="aud-landing"><div class="aud-welcome"><span class="aud-welcome-mark">${icon('spark')}</span><h2>这次，想找到哪些人？</h2><p>说出业务目标，帮你整理人群策略，找到合适的资产。</p></div><div class="aud-prompt-box">${seedAsset?`<div class="aud-seed-chip">已带入资产 · ${esc(seedAsset.name)}${button('移除','clear-seed','quiet small')}</div>`:''}<label class="aud-sr-only" for="aud-query">描述圈人需求</label><textarea id="aud-query" aria-label="描述圈人需求" placeholder="例如，为羽绒服新品找到近90天买过服饰、有相关兴趣的中高消费用户……">${esc(draftQuery)}</textarea>${upload.length?`<div class="aud-attachment-chips">${upload.map(x=>`<span>${icon('attach')}${esc(x.name)}</span>`).join('')}</div>`:''}<div class="aud-prompt-tools"><div class="aud-input-options"><label class="aud-attach-button" tabindex="0" role="button" aria-label="添加参考材料">${icon('attach')}<span>参考材料</span><input type="file" id="aud-material" accept=".md,.txt,.pdf,.png,.jpg,.jpeg" multiple></label><details class="aud-options"><summary>更多设置 <span>⌄</span></summary><div class="aud-options-popover"><label for="aud-scope">数据范围</label><select id="aud-scope" aria-label="任务数据范围"><option value="portal" ${scope==='portal'?'selected':''}>按需求匹配业务域</option><option value="ldmp" ${scope==='ldmp'?'selected':''}>仅生服 LDMP</option></select><label for="create-platform">使用平台 · 选填</label><input id="create-platform" aria-label="使用平台" value="${esc(draftPlatform)}" placeholder="可在交付前补充"><p>文本材料可读取；PDF 与图片目前仅记录文件名。</p></div></details></div>${button('开始圈人 '+icon('arrow'),'create','aud-start-button',!draftQuery.trim())}</div></div><div class="aud-input-caption"><span>只在关键口径不明确时向你提问</span><span>⌘ / Ctrl + Enter 发送</span></div><section class="aud-suggestions"><div class="aud-section-caption">也可以从这些场景开始</div><div class="aud-suggestion-grid">${E.featured.map(k=>{const [name,desc,mark]=sceneCopy[k];return `<button class="aud-suggestion" data-action="scene" data-key="${k}" aria-label="${name}示例"><span class="aud-suggestion-icon">${icon(mark)}</span><span><b>${name}</b><small>${desc}</small></span><span class="aud-suggestion-arrow">↗</span></button>`;}).join('')}</div></section><p class="aud-home-footnote">演示环境 · 策略与结果为模拟数据</p></main>`;}

function taskCard(t){return `<div class="archive-card" style="margin-bottom:10px"><div class="between"><div><span class="muted">${esc(t.id)} · v${t.version}</span><h3>${esc(t.title)}</h3></div>${badge(state(t),t.blocker?'amber':t.result?.approved?'green':'')}</div><p class="muted">${esc(t.query)}</p><div class="actions">${button('继续任务','resume','small',false,`data-id="${t.id}"`)}${button('复用为新任务','reuse','small',false,`data-id="${t.id}"`)}</div></div>`;}
const stageNotes=[
 ['任务创建','输入业务原话或带入门户资产，建立圈人任务。','一份保留原话与来源的任务'],
 ['我们已整理需求，只补关键问题','原话中明确的信息直接采用。只处理会改变入选范围的歧义与缺失。','需求理解单'],
 ['决定圈谁，以及为什么','比较保守、平衡和探索方案，确认取舍与排除范围。','人群策略卡'],
 ['系统核对资产与执行条件','口径映射、权限和版本由系统检查；只有缺口或条件变化需要你处理。','执行条件单'],
 ['执行后，再判断结果能不能用','根据确认版本运行，检查质量、记录业务反馈；有偏差可退回修改。','人群包与评估报告'],
 ['留下可复用、可追溯的方案','保存版本、采纳反馈与计划去向，为后续真实使用和效果回收留好关联。','策略档案']
];
function progress(t){const done=[true,t.confirmed,t.strategyConfirmed,t.conditionConfirmed,!!t.result,!!t.archived],available=artifactAvailability(t);return `<details class="aud-process-card" data-receipt="process-${t.version}" aria-label="任务执行清单"><summary class="between"><b>${workflowBusy?'正在推进任务':'本次任务进展'}</b><span>${done.filter(Boolean).length} / 6 项已完成 · 展开</span></summary><ol>${titles.map((name,i)=>`<li class="${done[i]?'done':i===t.stage?'current':''}"><span class="aud-process-check">${done[i]?'✓':String(i+1)}</span><div><b>${name}</b><small>${done[i]?outputs[i]+'已保留':i===t.stage?(t.blocker?'等待处理缺口':i===2?'等待选择口径':i===1?'只补充关键问题':i===5?'可按需保存模板':'处理中'):'待处理'}</small></div>${button('查看','view-artifact','quiet small',!available[i],`data-stage="${i}"`)}</li>`).join('')}</ol><p>过程记录展示操作、依据与产物摘要。</p></details>`;}
function workspace(t){return agentWorkspace(t);}
function left(t){return `<span class="label">业务原话</span><div class="bubble">${esc(t.query)}</div><span class="label">任务识别</span>${badge(t.type)}<div class="chatnote">${t.stage===0?'任务已建立。原话与参考材料已保留，下一步整理需求。':t.stage===1?'明确的原话直接采用；页面只追问影响入选范围的关键问题。':t.stage===2?'比较候选策略，先确认“圈谁、为什么”，再匹配资产。':t.stage===3?'每个核心条件都要有口径与权限依据。存在缺口时停止执行。':t.stage===4?'按当前已确认版本演示执行。真实 SQL Agent 接口尚未接入。':'保留版本与使用记录。业务采纳不等于策略已验证有效。'}</div>${t.attachedAssets.length?`<div class="attachment-context">门户带入 ${esc(t.attachedAssets.map(a=>a.name).join('、'))}<br>仅作需求参考，不自动获得权限。</div>`:''}<span class="label">材料来源</span><p class="muted">${esc(E.scenarios[t.scenario].source)}<br>场景为业务抽象示例，资产与自动校验为演示构造。</p>${t.materials.map(m=>`<div class="material">▧ ${esc(m.name)} · ${esc(m.note)}${m.text?`<details><summary>查看材料摘录</summary>${esc(m.text.slice(0,500))}</details>`:''}</div>`).join('')}<label class="filelabel">＋ 添加参考材料<input type="file" id="aud-material" accept=".md,.txt,.pdf,.png,.jpg,.jpeg" multiple></label><details><summary>补充说明与修改记录</summary><textarea id="aud-note" aria-label="补充说明" placeholder="记录补充依据；影响人群定义的内容请同时修改对应字段"></textarea>${button('记录说明','note','small')}<div>${t.notes.map(n=>`<p class="muted">${esc(n)}</p>`).join('')}</div></details>${button('修改需求 · 新版本','revise-need','small',!t.confirmed)}<details><summary>任务过程记录（${t.history.length}）</summary>${t.history.slice().reverse().map(x=>`<div class="runline"><span class="muted">v${x.version} · ${esc(x.at.slice(11,19))}</span><br>${esc(x.action)}</div>`).join('')}</details>`;}
function center(t){if(t.stage===0)return creation(t);if(t.stage===1)return understanding(t);if(t.stage===2)return strategies(t);if(t.stage===3)return conditions(t);if(t.stage===4)return execution(t);return archiveDetail(t);}
function creation(t){return section('任务卡已生成','业务原话、来源和后续产物绑定同一任务',`<div class="successbox">已识别为${esc(t.type)}任务。已明确的信息直接继承，下一步仅处理关键口径。</div><label class="label">业务原话</label><div class="bubble">${esc(t.query)}</div><div class="facts artifact-grid">${[['任务 ID',t.id],['业务场景',t.title],['使用平台',t.fields.platform.value],['资料来源',t.materials.length+' 份参考材料'+(t.attachedAssets.length?' · 门户资产带入':' · 业务输入')]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="action-footer"><span class="muted">任务已保存到当前浏览器</span>${button('进入需求理解 →','step','primary',false,'data-step="1"')}</div>`,badge('已创建','green'));}
function understandingTable(t){const pending=E.questions(t);const rows=[['目标需求',t.query,'原话提取','保留业务表达，不自行扩大目标'],['目标行为',t.fields.action.value,'场景理解',t.fields.action.source],['观察时间',t.fields.window.value?'近 '+t.fields.window.value+' 天':'待补充',t.fields.window.value?'原话 / 补充':'待补充',t.fields.window.source],['数据范围',t.fields.domain.value,'上下文提取',t.fields.domain.source],['兴趣定义',t.decisions?.interest||(/搜索|收藏|加购|互动/.test(t.query)?'按原话中的明确行为条件':pending.some(x=>x.id==='interest')?'待补充':'按原话；无额外兴趣限制'),pending.some(x=>x.id==='interest')?'待补充':'已明确','对应兴趣行为资产'],['消费口径',t.decisions?.spending||(pending.some(x=>x.id==='spending')?'待补充':'按原话；不额外提高门槛'),pending.some(x=>x.id==='spending')?'待补充':'已明确','真实分层以供应方定义为准'],['排除条件',t.fields.exclude.value,'业务约束','用户定义 + 平台治理约束'],['交付与验收',t.fields.success.value,'当前交付','不预填业务收益']];return section('结构化需求理解','自动整理，展示来源；明确的信息不再逐项确认',`<div class="table-scroll"><table class="understanding-table"><thead><tr><th>字段</th><th>结构化结果</th><th>状态</th><th>依据 / 处理</th></tr></thead><tbody>${rows.map(([k,v,status,why])=>`<tr><th>${k}</th><td>${esc(v)}</td><td>${badge(status,status==='待补充'?'amber':status==='已明确'||status==='原话提取'?'green':'')}</td><td class="muted">${esc(why||'业务输入')}</td></tr>`).join('')}</tbody></table></div>`);}

function understanding(t){
 if(!['直接圈人','复用历史策略','分析转圈人'].includes(t.type))return `<div class="warnbox"><b>识别为${esc(t.type)}请求</b><p>当前不能直接圈人。${t.type==='分析'?'先提供已有分析结论，再转成人群定义。':'需要对应业务或数据负责人处理。原始需求已保留。'}</p></div>${t.type==='分析'?`<textarea id="analysis-conclusion" aria-label="已有分析结论" placeholder="已有结论与希望圈选的人群"></textarea>${button('基于已有结论继续','analysis-convert','primary')}`:''}<div class="actions">${button('复制需求摘要','copy-route')}${button('返回创建','home')}</div>`;
 const pending=E.questions(t),answers=Object.entries(t.decisions||{});
 return `<details class="understanding-artifact"><summary>查看需求理解单 · 字段、来源与口径</summary>${understandingTable(t)}</details>${answers.length?`<details><summary>已补充的关键口径 · ${answers.length} 项</summary>${answers.map(([id,v])=>`<div class="summary-item"><p>${esc(v)}</p>${button('重新选择','reopen-decision','quiet small',t.confirmed,`data-id="${id}"`)}</div>`).join('')}</details>`:''}${t.confirmed?'<div class="successbox">当前理解已进入方案。需要调整时可修改需求并生成新版本。</div>':`<div class="section-head between"><h3>${pending.length?'只需要你补充 '+pending.length+' 个关键问题':'关键口径已清楚，可以继续'}</h3>${badge(pending.length?'影响人群范围':'无需逐项确认',pending.length?'amber':'green')}</div>${pending.length?pending.slice(0,3).map((q,i)=>`<div class="decision-card"><div class="decision-number">${i+1}</div><h3>${esc(q.title)}</h3><p>${esc(q.why)}</p><div class="decision-choices">${q.choices.map((v,n)=>button(esc(q.id==='window'?v+'天':v),'answer-choice','',false,`data-id="${q.id}" data-choice="${n}"`)).join('')}</div><details ${q.choices.length?'':'open'}><summary>填写业务已有口径</summary><input id="answer-${q.id}" aria-label="${esc(q.title)}" placeholder="填写具体规则或补充信息">${button('采用此口径','answer-custom','small',false,`data-id="${q.id}"`)}</details></div>`).join(''):'<p class="muted">明确条件不再重复提问。生成方案后仍可修改，资产存在性与权限将在执行前核验。</p>'}${pending.length>3?'<p class="muted">先完成以上关键问题，下一组问题随后展示。</p>':''}`}
 <details><summary>修改原始需求 / 查看其他信息</summary><textarea id="edit-query" aria-label="修改原始需求">${esc(t.query)}</textarea>${button('更新需求并重新理解','update-query','small')}<dl class="context-list">${['action','platform','exclude','success'].map(k=>`<dt>${labels[k]}</dt><dd>${esc(t.fields[k].value)}<span class="muted"> · ${esc(t.fields[k].source||t.fields[k].status)}</span></dd>`).join('')}</dl></details><div class="actions">${pending.length?'<span class="muted">补充完成后自动生成策略</span>':t.confirmed?'':button('生成策略','confirm-need','primary')}</div>`;
}
const strategySpecs=[['conservative','窄口径','增加核心行为频次门槛','可能遗漏低频但有潜力的用户'],['balanced','标准口径','完整保留业务条件，不额外加严','实际转化效果需实验验证'],['explore','偏好分层','在结果内补充分层','不扩大圈选范围']];
function strategyPreview(t,ids){const copy=E.clone(t);E.select(copy,ids);return copy.conditions;}
function strategyEvidence(t){const ids=t.strategy?.ids||[...picked],rules=t.conditions.length?t.conditions:strategyPreview(t,ids);return section('这份方案如何形成','业务要求 → 圈选判断 → 可执行条件',`<div class="aud-basis-list"><div><span>01 业务原话</span><p>${esc(t.query)}</p></div><div><span>02 补充口径</span><p>${Object.values(t.decisions||{}).map(esc).join('；')||'原话已包含关键定义，没有额外补充。'}</p></div><div><span>03 方案取舍</span><p>${ids.includes('conservative')?'窄口径在全部硬条件上增加核心行为至少 2 次的演示门槛。':'标准口径保留所有业务硬条件，不额外提高行为频次门槛。'}${ids.includes('explore')?'同时为符合条件的人群增加偏好分层，不改变入选范围。':''}</p></div></div><div class="aud-rule-preview">${rules.map(c=>`<div><span>${esc(c.group)}</span><b>${esc(c.name)}</b><p>${esc(c.value)}</p><small>来源 ${esc(c.owner)} · ${esc(c.assetVersion)}</small></div>`).join('')}</div>`)+historyEvidence(t);}
function historyEvidence(t){const prior=tasks.filter(x=>x.id!==t.id&&x.archived&&!x.invalid&&x.scenario===t.scenario);return `<details class="aud-history-evidence"><summary>历史方案与效果依据 · ${prior.length} 份同场景记录</summary><p class="muted">按场景筛选，仅作类比。人群、时间、触达方式和实验口径不同，历史收益不能直接当作本次预测。</p>${prior.length?prior.slice(0,3).map(x=>`<article><b>${esc(x.title)}</b><p>${esc(x.query)}</p>${(x.evidence||[]).filter(e=>e.version===x.version).map(e=>`<p>业务回填 · ${esc(e.metric)} · ${esc(e.conclusion)}<br>来源 ${esc(e.source)} · 实验 ${esc(e.experiment)} · V${e.version}<br>对照 ${esc(e.control)} / 实验 ${esc(e.treatment)} · ${esc(e.period)}</p>`).join('')||'<p>未回收实验结果，不引用收益结论。</p>'}${button('复用为新任务','reuse','quiet small',false,`data-id="${x.id}"`)}</article>`).join(''):'<p>暂无可引用的同场景历史记录。本次方案依据来自业务原话和补充口径。</p>'}</details>`;}
function strategies(t){const base=picked.has('conservative')?'conservative':'balanced';return `${t.templateConditions?.length?'<div class="info-strip">已带入模板的 '+t.templateConditions.length+' 条条件。执行前重新校验；旧人群结果不作为本次结果。</div>':''}<div class="section-head"><h3>这次更看重覆盖，还是明确意向？</h3><p class="muted">以下两种口径单选。共同的时间、消费条件和排除规则均保留。</p></div><div class="aud-scope-options">${['balanced','conservative'].map(id=>`<label class="aud-scope-option ${base===id?'selected':''}"><input type="radio" name="aud-scope-strategy" data-pick="${id}" ${base===id?'checked':''}><div><strong>${id==='balanced'?'标准口径':'窄口径'}</strong>${id==='balanced'?badge('建议起点'):''}<p>${id==='balanced'?'按已确认条件找人，保留较完整的候选范围。':'在共同条件上，额外要求核心行为至少出现 2 次。'}</p><small>${id==='balanced'?'适合先验证整体覆盖与转化；不承诺更高收益。':'演示门槛，意向更明确但可能漏掉低频潜客。'}</small></div></label>`).join('')}</div><label class="aud-extra-option"><input type="checkbox" data-pick="explore" ${picked.has('explore')?'checked':''}><span>同时增加偏好分层<small>仅为已入选的人群分组，方便后续分析，不扩大人群。</small></span></label><details><summary>查看本次方案的条件与来源</summary>${strategyPreview(t,[...picked]).map(c=>`<div class="summary-item"><b>${esc(c.name)}</b><p>${esc(c.value)}</p></div>`).join('')}</details>${historyEvidence(t)}<details><summary>补充策略说明</summary><textarea id="strategy-note" aria-label="策略调整说明">${esc(t.strategyDraftNote||t.strategy?.note||'')}</textarea></details><details><summary>演示异常分支</summary><select id="strategy-failure" aria-label="模拟协作异常"><option value="">正常完成</option><option value="permission">资产权限不足</option><option value="sql">执行失败</option></select></details><div class="action-footer">${button('修改需求','edit-current-query','quiet')}${button('采用'+(base==='balanced'?'标准口径':'窄口径')+'并执行','confirm-strategy','primary')}</div>`;}

function riskChecks(t){const errors=E.validation(t);return [['逻辑与取值',errors.some(x=>/条件|需求|方案/.test(x))?'需处理':'模拟通过'],['资产与口径',['missing','definition'].includes(t.blocker)?'已阻断':'模拟通过'],['权限',t.blocker==='permission'||t.conditions.some(x=>x.permission!=='演示可用')?'已阻断':'模拟通过'],['资产时效',t.blocker==='stale'?'已阻断':'模拟通过'],['跨域映射',t.blocker==='mapping'?'已阻断':t.fields.domain.value==='跨域'?'模拟通过':'不涉及'],['样本与覆盖','执行后评估']];}

function conditions(t){const errors=E.validation(t);return `${errors.length?`<div class="errorbox"><b>核心条件存在缺口 · 暂停执行</b><p>${esc(errors.join('、'))}。保留当前条件，处理完成后重新校验。</p></div>`:''}${section('条件逻辑编排','必须满足 AND（任一满足 OR）AND NOT 排除；平台治理约束始终保留',`<div class="condition-list">${t.conditions.map((c,i)=>`<div class="condition-row ${t.blocker==='permission'&&i===0?'blocked':''}"><div class="logic-token">${c.group==='排除'||c.group==='黑白名单'?'NOT':c.group==='任一满足'?'OR':'AND'}</div><div class="condition-main"><div class="row">${badge(c.group)}<strong>${esc(c.name)}</strong></div><p>${esc(c.value)}</p><div class="asset-meta">${esc(c.domain)} · ${esc(c.owner)} · ${esc(c.assetVersion)} · 更新 ${esc(c.updated)}</div><details><summary>资产依据${!t.conditionConfirmed&&!c.locked?'与条件修改':''}</summary><p class="muted">${esc(c.id)} · ${esc(c.definition)}</p><div class="form-grid"><select aria-label="${esc(c.name)}逻辑组" data-condition-group="${i}" ${t.conditionConfirmed||c.locked?'disabled':''}>${(c.group==='辅助分层'?['辅助分层']:['必须满足','任一满足','排除','频控','黑白名单']).map(g=>`<option ${g===c.group?'selected':''}>${g}</option>`).join('')}</select><input aria-label="${esc(c.name)}取值" data-condition-value="${i}" value="${esc(c.value)}" ${t.conditionConfirmed||c.locked?'disabled':''}></div></details></div><div class="condition-status">${badge(t.blocker==='permission'&&i===0?'模拟待授权':c.permission,t.blocker==='permission'&&i===0?'red':'green')}<p>${c.locked?'规则已锁定':c.core?'核心条件':'辅助分层'}</p></div></div>`).join('')}</div>`,badge('策略 V'+t.version))}${section('执行前检查','系统检查已构建条件，用户只处理缺口或业务取舍',`<div class="risk-grid">${riskChecks(t).map(([name,status])=>`<div class="risk-check ${status==='已阻断'||status==='需处理'?'error':status==='执行后评估'?'pending':''}"><b>${status==='已阻断'||status==='需处理'?'!':status==='执行后评估'?'○':'✓'} ${name}</b><span>${status}</span></div>`).join('')}</div>${t.blocker?`<div class="warnbox">${t.blocker==='permission'?'需资产 Owner 授权；门户入口可查看申请流程。':'需业务或供应方补齐依据，不会静默替换核心条件。'}<div class="actions">${button('查看门户申请入口','portal','small')}${button('模拟问题已解决','resolve','small')}</div></div>`:''}<details><summary>补充种子样本（可选）</summary><input id="seed-ref" aria-label="种子用户引用" placeholder="DEMO-SEED-01；仅填写演示标识" value="${esc(t.seedRef||'')}" ${t.conditionConfirmed?'disabled':''}></details><details><summary>演示异常分支</summary><select id="aud-blocker" aria-label="演示阻断类型"><option value="">全部演示检查通过</option>${Object.entries(E.blockers).filter(([k])=>!['sql','sample'].includes(k)).map(([k,v])=>`<option value="${k}" ${t.blocker===k?'selected':''}>${v}</option>`).join('')}</select></details><div class="action-footer">${button('修改策略','revise-strategy')}<div class="row">${t.conditionConfirmed?button('修改条件 · 新版本','revise-condition'):''}${button('按修改后的条件重新执行','check-and-execute','primary',errors.length>0)}</div></div>`)}<details><summary>查看结构化执行条件</summary><pre>${esc(JSON.stringify({task:t.id,version:t.version,conditions:t.conditions},null,2))}</pre></details>`;}

function execution(t){const r=t.result,last=t.runs.at(-1);const summary=r?`<div class="execution-summary">${[['运行状态','模拟执行完成'],['运行版本','V'+r.version],['人群规模',r.size.toLocaleString()+'（示例）'],['数据分区',r.partition]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div>`:`<div class="info-strip"><b>${running?'正在模拟执行…':'执行条件已就绪'}</b><span>按当前版本生成示例 SQL，回读人群与评估结果。</span></div>`;let panel='';if(executionTab==='sql')panel=`<div class="between"><span class="muted">${r?'模拟完成；未执行真实数据查询':'示例 SQL 预览 · 尚未执行'}</span>${badge('V'+t.version)}</div><pre class="sql-code">${esc(r?.sql||E.sql(t))}</pre>${r?`<div class="actions">${button('复制示例 SQL','copy-sql','small')}</div>`:''}`;if(executionTab==='logs')panel=`<div class="step-line">✓ 当前方案与执行条件版本一致</div><div class="step-line">✓ 演示条件通过检查，真实授权待接口接入</div>${t.runs.length?runs(t):'<div class="empty">尚未发起执行</div>'}`;if(executionTab==='audience')panel=r?`<h3>这批人为什么被圈入？</h3><p class="explanation">${esc(t.fields.definition.value)}</p><div class="info-strip">排除规则：${esc(t.fields.exclude.value)}</div><div class="sample-grid">${r.sampleIds.map(x=>`<div>${esc(x)}<span>演示标识 · 非真实用户</span></div>`).join('')}</div><p class="muted">仅提供 3 条演示样例。真实人群需在获准环境中交付。</p>`:'<div class="empty">执行后展示人群解释与演示样例</div>';if(executionTab==='quality')panel=r?`<div class="quality-list"><div><b>条件一致性</b><span>当前 V${r.version} 的规则已绑定运行记录</span>${badge('模拟通过','green')}</div><div><b>资产覆盖</b><span>部分偏好资产覆盖不足，真实执行时需核实</span>${badge('待核实','amber')}</div><div><b>种子样本</b><span>${t.seedRef?'已关联 '+esc(t.seedRef)+'；命中情况为演示':'未提供，不生成种子命中结论'}</span>${badge(t.seedRef?'已关联':'未评估')}</div><div><b>业务收益</b><span>需要消费方实验回传，人群规模不代表增量收益</span>${badge('待验证')}</div></div>`:'<div class="empty">执行后生成质量评估，不提前展示评分</div>';return `${r?`<div class="aud-result-intro"><h3>本次圈中了哪些人</h3><p>${esc(t.query)}</p><div class="aud-result-facts"><span>近 ${esc(t.fields.window.value)} 天 · ${esc(t.fields.domain.value)}</span><span>${t.strategy?.ids.includes('conservative')?'窄口径 · 核心行为至少 2 次':'标准口径 · 保留业务硬条件'}</span></div><p class="muted">${t.strategy?.ids.includes('explore')?'已添加偏好分层；未扩大入选范围。':'未添加额外偏好分层。'}业务收益待实验验证。</p></div><details class="aud-result-conditions"><summary>查看入选与排除条件 · ${t.conditions.length} 条</summary>${conditionOverview(t)}</details>`:''}${summary}${last?.status==='失败'&&!r?`<div class="errorbox">${esc(last.reason)} · 连续失败 ${t.attempts}/3。${t.attempts>=3?'已停止自动尝试，请转人工处理。':'检查条件后可重试。'}</div>`:''}${section('执行与评估','SQL、运行记录、人群说明和质量判断绑定同一版本',`<div class="execution-tabs" role="tablist">${[['sql','SQL'],['logs','运行日志'],['audience','人群解释'],['quality','质量评估']].map(([id,label])=>`<button role="tab" aria-selected="${executionTab===id}" data-action="execution-tab" data-tab="${id}" class="${executionTab===id?'active':''}">${label}</button>`).join('')}</div><div role="tabpanel" class="execution-pane">${panel}</div>`)}${r?`${section('业务复核','仅记录是否符合需求，效果验证在业务实验后回收',`<textarea id="review-feedback" aria-label="业务抽检反馈" placeholder="可记录偏差、抽检结论或修改建议">${esc(t.feedback)}</textarea><div class="action-footer"><div class="row">${button('退回修改策略','revise-strategy')}${button('退回修改条件','revise-condition')}</div><div class="row">${button('评估报告','report')}${button('导出演示包','export-csv')}${r.approved?button('保存模板与复盘','view-artifact','primary',false,'data-stage="5"'):button('结果符合需求','approve','primary')}</div></div>`)}`:`<details><summary>执行异常演示</summary><select id="run-failure" aria-label="模拟执行结果"><option value="">模拟成功</option><option value="sql" ${runFailure==='sql'?'selected':''}>SQL 执行失败</option><option value="sample" ${runFailure==='sample'?'selected':''}>结果样本量过小</option></select></details><div class="action-footer">${button('返回条件','back-condition','',running)}${button(t.attempts>=3?'下载人工处理记录':running?'正在执行…':t.attempts?'重试模拟执行':'运行演示',t.attempts>=3?'report':'run','primary',running||(!E.executable(t)&&t.attempts<3))}</div>`}`;}

function runs(t){return t.runs.map(r=>`<div class="runline">${esc(r.id)} · v${r.version} · ${esc(r.status)} ${r.reason?' / '+esc(r.reason):''}<br><span class="muted">${esc(r.at)}</span></div>`).join('');}
function compare(t,v){const old=t.versions.find(x=>x.version===v);if(!old)return '';return `<div class="compare">${[[v,old],[t.version,t]].map(([version,item])=>`<div><b>V${version} · ${version===t.version?'当前':'历史'}</b><p>${esc(item.query||item.fields.object.value)}</p><p class="muted">策略 ${esc(item.strategy?.ids.join(' / ')||'未确认')}</p>${item.conditions.map(c=>`<p><b>${esc(c.group)} · ${esc(c.name)}</b>${esc(c.value)}</p>`).join('')}<p>${item.result?'模拟结果 '+item.result.size.toLocaleString()+' 人':'暂无结果'}</p></div>`).join('')}</div>`;}
function archiveDetail(t){return section('保存为圈人模板','本次结果保留在原会话；复用模板时新建任务，重新校验并圈选',`<div class="successbox">当前 V${t.version} 已通过业务复核${t.archived?'，模板已保存':'，可以按需保存为模板'}。${t.result?`已关联 ${t.result.size.toLocaleString()} 人的演示结果。`:''}</div><label class="label" for="archive-title">模板名称</label><input id="archive-title" value="${esc(t.title)}"><div class="form-grid"><div><label class="label" for="adoption">业务采纳状态</label><select id="adoption">${['未采纳','计划使用','已采纳（用户反馈）','不采纳'].map(x=>`<option ${x===t.adoption?'selected':''}>${x}</option>`).join('')}</select></div><div><label class="label" for="destination">使用去向 / 负责人 · 选填</label><input id="destination" value="${esc(t.destination)}" placeholder="仅记录计划，不实际下发"></div></div><p class="muted">一并保存业务原话、补充口径、策略、条件、SQL、结果与复核意见。采纳不等于已经验证收益。</p><div class="actions">${button('下载本次记录','report','small')}${button(t.archived?'更新模板':'保存为圈人模板','archive','primary')}</div><details><summary>版本与复用管理 · 当前 V${t.version}</summary>${t.versions.map(v=>`<div class="version-row"><div><b>V${v.version}</b><p class="muted">${esc(v.reason)}</p></div><div class="row">${button('查看差异','compare','small',false,`data-version="${v.version}"`)}${button('恢复为新版本','restore','small',false,`data-version="${v.version}"`)}</div></div>`).join('')||'<p class="muted">暂无历史版本，修改策略或条件时会保留原版本。</p>'}${compareVersion?compare(t,compareVersion):''}<div class="actions">${button(t.invalid?'恢复有效':'标记模板失效','toggle-invalid','small',!t.archived)}</div></details>`,badge(t.invalid?'已失效':t.archived?'已保存':'待保存',t.invalid?'amber':'green'));}

function effectReview(t){const evidence=(t.evidence||[]).filter(e=>e.version===t.version);return section('效果回收与下一轮改进','由业务方回填实验结果或 LR 文档；与当前任务和版本关联',`<p class="muted">人群规模、采纳状态与业务收益分别记录。缺少实验对照时，不判断增量收益。</p>${evidence.map(e=>`<div class="successbox"><b>${esc(e.metric)} · ${esc(e.conclusion)}</b><p>业务回填，未自动核验 · ${esc(e.experiment)} · V${e.version}</p><p>对照 ${esc(e.control)} / 实验 ${esc(e.treatment)} · ${esc(e.period)}</p><p>来源 ${esc(e.source)}</p></div>`).join('')}<div class="form-grid">${[['experiment','实验标识','例如 EXP-2026-001'],['metric','收益指标与单位','例如 支付转化率（%）'],['control','对照组结果','数值及口径'],['treatment','实验组结果','数值及口径'],['period','实验周期与适用人群','日期、人群和触达范围'],['source','LR 文档或结果来源','填写文档链接或来源标识']].map(([key,label,placeholder])=>`<div><label class="label" for="effect-${key}">${label}</label><input id="effect-${key}" data-effect-field="${key}" value="${esc(t.effectDraft?.[key]||'')}" placeholder="${placeholder}"></div>`).join('')}</div><label class="label" for="effect-conclusion">业务结论与限制</label><textarea id="effect-conclusion" data-effect-field="conclusion" placeholder="例如：未达显著性；继续补样本，暂不推广">${esc(t.effectDraft?.conclusion||'')}</textarea><div class="actions">${button('关联本次效果记录','save-evidence','primary')}</div><details><summary>人群特征分析如何用于下一轮优化</summary><div class="aud-basis-list"><div><span>需要的输入</span><p>实验分组、触达与转化结果、人群特征、指标定义，以及有效的样本与权限。当前 Demo 未接入这些输入。</p></div><div><span>分析能力返回</span><p>可比较的分层差异、候选人群特征与证据限制。HTE 能力的输入格式和服务接口待与供应方确认。</p></div><div><span>下一轮任务</span><p>将分析结论作为新假设，生成新版本；重新圈选并做对照实验验证，保留当前版本结果。</p></div></div>${button('基于反馈创建下一轮任务','reuse','small',!evidence.length,`data-id="${t.id}"`)}</details>`);}

function archives(){const saved=tasks.filter(t=>t.archived);return `<div class="aud-asset-library"><div class="strip"><span>${saved.length} 份圈人模板</span><span class="muted">完成复核并明确保存的方案，可用于后续需求复用</span></div><div class="archive-list">${saved.slice().reverse().map(taskCard).join('')||`<div class="panel empty"><h3>还没有保存的圈人模板</h3><p>日常任务已保留在左侧历史会话中。完成圈选并复核后，可将方案保存到这里。</p>${button('开始新会话','home','primary')}</div>`}</div></div>`;}

function exportFile(t,type){if(type==='csv'){if(!t.result||t.result.version!==t.version)throw Error('无当前有效人群结果');download('demo-audience-'+t.id+'.csv','demo_user_id,task_version\n'+t.result.sampleIds.map(x=>x+','+t.version).join('\n'),'text/csv');}else download('demo-plan-'+t.id+'-v'+t.version+'.json',JSON.stringify({demo:true,productionExecution:false,...t},null,2),'application/json');}
function download(name,text,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function fileInput(input){const target=current();const list=[];for(const f of input.files){if(f.size>2*1024*1024){message='单份演示材料请小于 2MB';continue;}const text=/\.(md|txt)$/i.test(f.name)?await f.text():null;list.push({name:f.name,note:text?'已读取文本，需人工确认引用':'已记录文件名，未接入图片/PDF解析',text});}if(view==='task'&&target){target.materials.push(...list);E.log(target,'补充材料；未自动改写条件');}else upload.push(...list);persist();render();}
function bind(){filterSessionHistory();for(const [id,key] of [['archive-title','title'],['adoption','adoption'],['destination','destination'],['strategy-note','strategyDraftNote']])host.querySelector('#'+id)?.addEventListener('input',e=>{needTask()[key]=e.target.value;persist();});host.querySelectorAll('[data-effect-field]').forEach(n=>n.addEventListener('input',()=>{const t=needTask();(t.effectDraft||(t.effectDraft={}))[n.dataset.effectField]=n.value;persist();}));
 host.querySelector('#aud-followup')?.addEventListener('input',e=>{current().chatDraft=e.target.value;persist();host.querySelector('[data-action="send-followup"]').disabled=!e.target.value.trim();});
 host.querySelector('#aud-followup')?.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!e.isComposing&&e.target.value.trim()){e.preventDefault();dispatch('send-followup',{});}});
 host.querySelector('#review-feedback')?.addEventListener('input',e=>{current().feedback=e.target.value;persist();});
 host.onkeydown=e=>{if(e.key==='Escape'&&artifactView!==null){e.preventDefault();dispatch('close-artifact',{});}};host.querySelector('#aud-history-search')?.addEventListener('input',e=>{historySearch=e.target.value;filterSessionHistory();});host.querySelector('#aud-query')?.addEventListener('input',e=>{draftQuery=e.target.value;const submit=host.querySelector('[data-action=create]');if(submit)submit.disabled=!draftQuery.trim();});host.querySelector('#aud-query')?.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!e.isComposing){e.preventDefault();if(e.target.value.trim())dispatch('create',{});}});host.querySelector('#create-platform')?.addEventListener('input',e=>draftPlatform=e.target.value);host.querySelector('.aud-attach-button')?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();host.querySelector('#aud-material')?.click();}});host.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>dispatch(b.dataset.action,b.dataset)));host.querySelectorAll('[data-field]').forEach(n=>{if(n.tagName==='INPUT')n.addEventListener('change',()=>{const t=needTask();if(t.confirmed)return;t.fields[n.dataset.field]={value:n.value,status:'待确认'};persist();});});host.querySelectorAll('[data-pick]').forEach(n=>n.addEventListener('change',()=>{const note=host.querySelector('#strategy-note')?.value;if(n.dataset.pick==='explore'){if(n.checked)picked.add('explore');else picked.delete('explore');}else{picked.delete('balanced');picked.delete('conservative');picked.add(n.dataset.pick);}current().strategyDraft=[...picked];current().strategyDraftNote=note||'';persist();render();if(note!==undefined)host.querySelector('#strategy-note').value=note;}));host.querySelectorAll('[data-condition-value]').forEach(n=>n.addEventListener('change',()=>{const t=needTask();t.conditions[+n.dataset.conditionValue].value=n.value;persist();render();}));host.querySelectorAll('[data-condition-group]').forEach(n=>n.addEventListener('change',()=>{const t=needTask();t.conditions[+n.dataset.conditionGroup].group=n.value;persist();render();}));host.querySelector('#aud-material')?.addEventListener('change',e=>fileInput(e.target));host.querySelector('#aud-scope')?.addEventListener('change',e=>scope=e.target.value);host.querySelector('#aud-blocker')?.addEventListener('change',e=>{const t=needTask();if(t.conditionConfirmed||t.result)E.revise(t,3,'模拟资产状态发生变化');t.blocker=e.target.value||null;E.log(t,'演示校验状态变更');persist();render();});host.querySelector('#run-failure')?.addEventListener('change',e=>runFailure=e.target.value);}
async function dispatch(action,d){try{message='';let t=current();if(action==='resume'&&d.id===active&&view==='task')return;if(['home','resume','archives'].includes(action)){rememberSession();if(action!=='resume'||d.id!==active)stopOperation(t,'切换会话，未完成的操作已暂停，可返回继续');}if(workflowBusy&&!['pause-workflow','toggle-history','resume','home','close-artifact','view-artifact','open-deliverables'].includes(action))throw Error('正在处理，请等待完成或先暂停');switch(action){
case 'toggle-history':{historyOpen=!historyOpen;const shell=host.querySelector('.aud-session-shell');shell.classList.toggle('history-open',historyOpen);shell.classList.toggle('history-closed',!historyOpen);const toggle=host.querySelector('.aud-history-toggle');toggle.setAttribute('aria-expanded',String(historyOpen));toggle.setAttribute('aria-label',(historyOpen?'收起':'展开')+'历史会话');return;}
case 'view-artifact':drawerReturn={action,stage:d.stage};if(artifactView===null)historyOpen=false;artifactView=+d.stage;break;
case 'open-deliverables':drawerReturn={action};historyOpen=false;artifactView='all';break;
case 'open-handoff':drawerReturn={action};historyOpen=false;artifactView='handoff';break;
case 'edit-current-query':t.chatDraft=t.query;persist();render();host.querySelector('#aud-followup')?.focus();return;
case 'close-artifact':artifactView=null;render();[...host.querySelectorAll(drawerReturn?'[data-action="'+drawerReturn.action+'"]'+(drawerReturn.stage!==undefined?'[data-stage="'+drawerReturn.stage+'"]':''):'#aud-followup')].find(n=>n.getClientRects().length)?.focus({preventScroll:true});return;
case 'pause-workflow':stopOperation(t,'业务暂停；未完成操作不会标记为成功');break;
case 'resume-workflow':if(!t.confirmed)await understandFlow(t);else if(t.strategyConfirmed&&!t.result?.approved)await executeFlow(t);else await operate(t,'圈人 Agent 正在恢复任务',[{title:'恢复已确认产物',work:()=>{t.stage=t.result?.approved?5:2;return t.result?.approved?'已恢复复核结果，可以继续整理和保存策略档案':'候选方案已恢复，请选择本次策略';}}]);break;
case 'home':artifactView=null;draftQuery='';draftPlatform='';view='home';active=null;compareVersion=null;seedAsset=null;upload=[];break;
case 'archives':artifactView=null;view='archive';break;
case 'scene':draftQuery=E.scenarios[d.key].query;host.querySelector('#aud-query').value=draftQuery;host.querySelector('[data-action=create]').disabled=false;host.querySelector('#aud-query').focus();return;
case 'clear-seed':seedAsset=null;break;
case 'execution-tab':if(host.querySelector('#review-feedback'))t.feedback=host.querySelector('#review-feedback').value;executionTab=d.tab;break;
case 'toggle-invalid':if(!t.archived)throw Error('请先保存档案');t.invalid=!t.invalid;E.log(t,t.invalid?'标记策略失效':'恢复策略有效');break;
case 'create':{const q=host.querySelector('#aud-query').value.trim();if(!q){notify('请先描述圈人需求');return;}t=E.create(q,null,scope);t.stage=0;const platform=host.querySelector('#create-platform')?.value.trim();if(platform)t.fields.platform={value:platform,status:'已明确',source:'创建任务时填写'};draftQuery='';t.materials=upload;upload=[];if(seedAsset)t.attachedAssets.push(seedAsset);tasks.push(t);active=t.id;view='task';if(host.clientWidth<850)historyOpen=false;picked=new Set(['balanced']);E.log(t,'创建演示任务，自动整理需求');await understandFlow(t);break;}
case 'resume':artifactView=null;active=d.id;view='task';executionTab='audience';{const ids=current().strategyDraft||current().strategy?.ids||['balanced'];picked=new Set([ids.includes('balanced')?'balanced':ids.includes('conservative')?'conservative':'balanced',...(ids.includes('explore')?['explore']:[])]);}current().lastOpened=new Date().toISOString();if(host.clientWidth<850)historyOpen=false;break;
case 'reuse':{const src=tasks.find(x=>x.id===d.id);t=E.create(src.query,src.scenario,src.scope);if(src.invalid)throw Error('该策略已失效，请新建任务');t.fields=E.clone(src.fields);t.decisions=E.clone(src.decisions||{});Object.values(t.fields).forEach(f=>f.status=f.value?'系统推断':'待确认');t.title=src.title+' · 复用';t.reuse=true;t.templateConditions=E.clone(src.conditions);t.templateStrategy=E.clone(src.strategy?.ids||['balanced']);t.reusedFrom={id:src.id,version:src.version};t.notes.push('来源方案 '+src.id+' / V'+src.version+'；复用条件，重新核验，不复用旧人群结果。');if(src.evidence?.length)t.notes.push('历史效果仅供参考：'+src.evidence.filter(e=>e.version===src.version).map(e=>e.metric+' / '+e.conclusion+' / '+e.source).join('；'));tasks.push(t);active=t.id;view='task';E.log(t,'复用历史方案；口径、权限与时间需要重新确认');await understandFlow(t);break;}
case 'save':E.log(needTask(),'保存草稿');message='草稿已保存到当前浏览器';break;
case 'note':{const note=host.querySelector('#aud-note').value.trim();if(note){t.notes.push(note);E.log(t,'记录补充说明，条件未自动改变');}break;}
case 'confirm-field':{const n=host.querySelector('#field-'+d.field);const val=n.value.trim();if(!val)throw Error('请先填写该项');if(d.field==='window'&&(!/^\d+$/.test(val)||+val<1||+val>3650))throw Error('时间窗口请输入 1–3650 的整数天数');if(d.field==='domain'&&!['生服','跨域'].includes(val))throw Error('本演示业务域请选择生服或跨域');t.fields[d.field]={value:val,status:'已确认'};break;}
case 'na-field':t.fields[d.field]={value:'不适用（业务确认）',status:'不适用'};break;

case 'direct-definition':{const source=host.querySelector('#direct-source').value.trim();if(!source)throw Error('请记录完整定义来源');E.confirm(t);E.select(t,['direct']);t.strategy.evidence=source;t.strategy.note='业务已提供完整定义，确认人为当前演示用户';E.log(t,'记录定义来源并跳过候选策略');break;}
case 'answer-choice':{const q=E.questions(t).find(q=>q.id===d.id);if(!q)throw Error('问题已更新');const value=q.choices[+d.choice];addChat(t,q.title+'\n'+value);if(t.interactionVersion===2)E.answer(t,d.id,value);else t.fields[d.id]={value,status:'已确认'};if(!E.questions(t).length)await understandFlow(t);break;}
case 'answer-custom':{const value=host.querySelector('#answer-'+d.id).value.trim();if(!value)throw Error('请填写具体口径');addChat(t,(E.questions(t).find(q=>q.id===d.id)?.title||'补充口径')+'\n'+value);if(t.interactionVersion===2)E.answer(t,d.id,value);else t.fields[d.id]={value,status:'已确认'};if(!E.questions(t).length)await understandFlow(t);break;}
case 'reopen-decision':if(t.confirmed)throw Error('请先修改需求');delete t.decisions[d.id];if(d.id==='window')t.fields.window={value:'',status:'待补充'};break;
case 'send-followup':
case 'update-query':{const q=host.querySelector(action==='send-followup'?'#aud-followup':'#edit-query').value.trim();if(!q)throw Error('请输入需求');const next=E.create(q,null,t.scope);chatHistory(t);E.revise(t,1,'更新业务原话');addChat(t,q);t.chatDraft='';t.strategyDraft=null;t.templateConditions=null;t.templateStrategy=null;for(const k of ['query','scenario','title','type','fields','decisions','interactionVersion'])t[k]=next[k];await understandFlow(t);break;}
case 'check-and-execute':{if(t.blocker||!t.confirmed||!t.strategyConfirmed||!t.conditions.length||t.conditions.some(c=>!c.value.trim()||c.permission!=='演示可用'))throw Error('存在未解决的执行缺口');const ref=host.querySelector('#seed-ref').value.trim();if(ref&&!/^DEMO-/.test(ref))throw Error('演示种子引用须以 DEMO- 开头');t.seedRef=ref;t.conditionConfirmed=true;if(!E.executable(t)){t.conditionConfirmed=false;throw Error('数据范围不符合当前入口');}E.log(t,'模拟系统检查通过，进入执行评估');t.stage=4;await executeFlow(t);break;}
case 'confirm-need':await understandFlow(t);break;
case 'analysis-convert':{const value=host.querySelector('#analysis-conclusion').value.trim();if(!value)throw Error('请提供已有分析结论与目标人群');t.type='分析转圈人';t.notes.push(value);t.fields.object={value,status:'待确认'};E.log(t,'已有结论进入需求确认，未自动开展分析');break;}
case 'copy-route':await navigator.clipboard.writeText(t.query+'\n任务类型：'+t.type+'\n当前需转交对应负责人');message='已复制需求摘要';break;
case 'confirm-strategy':{const note=host.querySelector('#strategy-note')?.value||'';const fail=host.querySelector('#strategy-failure')?.value||'';t.blocker=fail==='permission'?'permission':null;runFailure=fail==='sql'?'sql':'';addChat(t,'采用'+[...picked].map(id=>strategySpecs.find(x=>x[0]===id)?.[1]||id).join(' + ')+'，检查条件并试跑。');await executeFlow(t,true);if(t.strategy)t.strategy.note=note;break;}
case 'revise-need':E.revise(t,1,'修改需求');await operate(t,'圈人 Agent 正在准备需求调整',[{title:'保留原有方案与结果快照',work:()=> '原版本已保留；请在下方修改业务原话，再重新生成本次方案'}]);break;
case 'revise-strategy':E.revise(t,2,'修改策略');picked=new Set([t.strategy?.ids.includes('conservative')&&!t.strategy?.ids.includes('balanced')?'conservative':'balanced',...(t.strategy?.ids.includes('explore')?['explore']:[])]);await operate(t,'圈人 Agent 正在准备策略调整',[{title:'保存历史版本并使旧结果失效',work:()=> '历史结果已保留，当前候选等待重新选择'}]);break;
case 'revise-condition':E.revise(t,3,'修改执行条件');await operate(t,'圈人 Agent 正在准备条件调整',[{title:'标记当前结果待重算',work:()=> '保留原有结果与执行回执；条件修改后须重新校验与执行'}]);artifactView=3;break;
case 'confirm-condition':if(t.blocker||t.conditions.some(c=>!c.value.trim()))throw Error('请先补齐核心条件与缺口');t.seedRef=host.querySelector('#seed-ref').value;if(t.seedRef&&!/^DEMO-/.test(t.seedRef))throw Error('演示种子引用须以 DEMO- 开头，请勿使用真实 UID');t.conditionConfirmed=true;E.log(t,'执行条件单已确认');break;
case 'resolve':E.revise(t,3,'模拟缺口解决，重新核验条件');t.blocker=null;message='仅恢复模拟状态，未修改真实权限';await executeFlow(t);break;
case 'to-execute':if(!E.executable(t))throw Error('条件未通过校验');t.stage=4;break;
case 'back-condition':t.stage=3;break;
case 'run':await executeFlow(t);break;
case 'approve':t.feedback=host.querySelector('#review-feedback')?.value||t.feedback;addChat(t,'已复核本次模拟结果。'+(t.feedback||''));await operate(t,'圈人 Agent 正在整理复核结论',[{title:'记录业务复核意见',work:()=>{E.approve(t);return '本次结果复核通过，保留业务反馈';}},{title:'整理关联产物',artifact:4,work:()=> '准备保存本次人群结果与可复用模板；效果状态仍为待验证'}]);artifactView=5;break;
case 'archive':if(!t.result?.approved)throw Error('请先通过结果复核');t.title=host.querySelector('#archive-title').value.trim()||t.title;t.adoption=host.querySelector('#adoption').value;t.destination=host.querySelector('#destination').value;if(await archiveFlow(t))message='已保存策略档案、执行回执与过程摘要';break;
case 'save-evidence':{const values={};host.querySelectorAll('[data-effect-field]').forEach(n=>values[n.dataset.effectField]=n.value.trim());E.recordEvidence(t,values);t.effectDraft={};message='已关联当前版本，作为业务回填记录；未自动验证收益';break;}
case 'copy-sql':if(!t.result)throw Error('请先执行');await navigator.clipboard.writeText(t.result.sql);message='已复制示例 SQL，不可用于生产';break;
case 'export-csv':exportFile(t,'csv');message='已导出 3 条 DEMO 标识样例，不含真实 UID';break;
case 'report':exportFile(t,'json');message='已下载带版本的演示档案';break;
case 'step':{const step=+d.step;if(step===2&&!t.confirmed)throw Error('需求尚未确认');if(step===3&&!t.strategyConfirmed)throw Error('策略尚未确认');if(step===4&&!E.executable(t))throw Error('条件尚未通过');if(step===5&&!t.result?.approved)throw Error('结果尚未复核');t.stage=step;break;}
case 'compare':compareVersion=+d.version;break;
case 'restore':E.restore(t,+d.version);compareVersion=null;await understandFlow(t);break;
case 'portal':if(options.onPortal)options.onPortal();else location.href='https://utup-mvp-frontend.vercel.app/#myperm';return;
}persist();render();if(action==='send-followup'){const stream=host.querySelector('.aud-chat-stream');if(stream)stream.scrollTop=stream.scrollHeight;}if(['create','resume','reuse','confirm-need','confirm-strategy','to-execute','approve','step','home','archives','direct-definition','check-and-execute','update-query','revise-need','revise-strategy','revise-condition','restore'].includes(action)){host.scrollIntoView({block:'start'});}}catch(e){running=false;notify(e.message||'操作失败，请重试');}}
window.AudienceWorkspace={mount,unmount(){stopOperation(current(),'已离开工作区，未完成操作暂停');persist();host=null;options={};},openAsset(asset){seedAsset=asset?{id:String(asset.id),name:asset.name}:null;active=null;upload=[];view='home';render();},show(viewName){view=viewName;render();}};
})();
